import json
import os
import sys
from .cmd_codex_install import _remove_export_from_shellrc, _detect_shell_rc, PROVIDER_ENV_KEY
from .backup_utils import backup_existing_file

CODEX_DIR = os.path.expanduser("~/.codex")
CODEX_CONFIG_FILE = os.path.join(CODEX_DIR, "config.toml")
HOOKS_FILE = os.path.join(CODEX_DIR, "hooks.json")


def log_error(msg: str):
    print(f"\n\033[31m[错误] {msg}\033[0m", file=sys.stderr)


def log_warning(msg: str):
    print(f"\n\033[33m[警告] {msg}\033[0m")


def log_success(msg: str):
    print(f"\033[32m{msg}\033[0m")


def _remove_ahclaude_sections(content: str) -> str:
    lines = content.split("\n")
    result = []
    skip = False
    for line in lines:
        if line.strip() == "# BEGIN auto++":
            skip = True
            continue
        if line.strip() == "# END auto++":
            skip = False
            continue
        if not skip:
            result.append(line)
    while result and result[-1].strip() == "":
        result.pop()
    return "\n".join(result)


def _remove_section(content: str, section_name: str) -> str:
    """移除指定的 [section] 及其所有子节（含 section_name.xxx 形式）"""
    bare = section_name.strip("[]")
    lines = content.split("\n")
    result = []
    skip = False
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("[") and stripped.endswith("]"):
            inner = stripped.strip("[]")
            if inner == bare or inner.startswith(bare + "."):
                skip = True
                continue
            else:
                skip = False
        if not skip:
            result.append(line)
    return "\n".join(result)


def _is_auto_command(command: str) -> bool:
    if not command:
        return False
    return "ahclaude_plugin" in command or "auto++" in command


def remove_hooks_json():
    """从 hooks.json 中移除 auto++ 相关的 hook 条目"""
    if not os.path.exists(HOOKS_FILE):
        return

    try:
        with open(HOOKS_FILE, "r", encoding="utf-8") as f:
            hooks_data = json.load(f)
    except (json.JSONDecodeError, IOError):
        return

    if "hooks" not in hooks_data:
        return

    changed = False
    for event in list(hooks_data["hooks"].keys()):
        before = len(hooks_data["hooks"][event])
        hooks_data["hooks"][event] = [
            entry for entry in hooks_data["hooks"][event]
            if not any(
                _is_auto_command(h.get("command", ""))
                for h in entry.get("hooks", [])
            )
        ]
        removed = before - len(hooks_data["hooks"][event])
        if removed > 0:
            print(f"  已清理 {removed} 个 {event} Hook")
            changed = True
        if not hooks_data["hooks"][event]:
            del hooks_data["hooks"][event]

    if not hooks_data.get("hooks"):
        hooks_data.pop("hooks", None)

    if changed:
        new_content = json.dumps(hooks_data, ensure_ascii=False, indent=2)
        backup_existing_file(HOOKS_FILE, "Codex hooks.json", new_content)
        with open(HOOKS_FILE, "w", encoding="utf-8") as f:
            f.write(new_content)
        print(f"已清理 hooks.json: {HOOKS_FILE}")


def remove_config():
    config_changed = False

    # 清理 config.toml 中的 auto++ 相关配置
    if os.path.exists(CODEX_CONFIG_FILE):
        try:
            with open(CODEX_CONFIG_FILE, "r", encoding="utf-8") as f:
                content = f.read()
        except IOError as e:
            log_error(f"读取配置文件失败: {e}")
            raise

        cleaned = _remove_ahclaude_sections(content)

        # 清理 auto++ 注入的顶层 key（model/model_provider/model_catalog_json）
        top_keys_to_remove = {"model", "model_provider", "model_catalog_json"}
        filtered_lines = []
        in_section = False
        for line in cleaned.split("\n"):
            stripped = line.strip()
            if stripped.startswith("[") and not stripped.startswith("[["):
                in_section = True
            if not in_section:
                key_name = stripped.split("=")[0].strip()
                if key_name in top_keys_to_remove:
                    config_changed = True
                    continue
            filtered_lines.append(line)
        cleaned = "\n".join(filtered_lines)

        # 清理 autohome provider 配置（marketplaces 已不再移除，影响桌面端会话历史）
        for section in [
            "[model_providers.autohome]",
        ]:
            before_len = len(cleaned)
            cleaned = _remove_section(cleaned, section)
            if len(cleaned) != before_len:
                print(f"  已清理: {section}")
                config_changed = True

        try:
            backup_existing_file(CODEX_CONFIG_FILE, "Codex config.toml", cleaned)
            with open(CODEX_CONFIG_FILE, "w", encoding="utf-8") as f:
                f.write(cleaned)
            print(f"已清理 Codex 配置: {CODEX_CONFIG_FILE}")
        except IOError as e:
            log_error(f"保存配置文件失败: {e}")
            raise
    else:
        print("未找到 Codex 配置文件，跳过")

    # 清理模型目录文件
    model_catalog_file = os.path.join(CODEX_DIR, "model-catalogs", "autohome.json")
    if os.path.exists(model_catalog_file):
        try:
            os.remove(model_catalog_file)
            print(f"已移除模型目录: {model_catalog_file}")
        except OSError as e:
            log_warning(f"清理模型目录失败: {e}")

    # 非 Windows 才清理 shell rc 中 auto++ 历史写入的 export 块。
    if sys.platform != "win32":
        rc_file = _detect_shell_rc()
        try:
            for env_key in ("OPENAI_API_KEY", PROVIDER_ENV_KEY):
                _remove_export_from_shellrc(rc_file, env_key)
                print(f"已移除 {env_key}: {rc_file}")
        except IOError as e:
            log_warning(f"清理 shell rc 失败: {e}")

    return config_changed


def uninstall():
    print("=" * 50)
    print("auto++ 卸载向导 (Codex)")
    print("=" * 50)
    print()

    try:
        print("[步骤 1] 移除 Codex 配置...")
        remove_config()

        print()
        print("=" * 50)
        log_success("移除配置完成!")
        print("=" * 50)
        print()
        print("请重启 Codex 以使更改生效")

    except KeyboardInterrupt:
        log_warning("\n移除配置已取消")
        sys.exit(1)
    except Exception as e:
        log_error(f"移除配置失败: {e}")
        sys.exit(1)


if __name__ == "__main__":
    uninstall()
